// One output per slot (keep the number of outputs equal to SLOT_COUNT).
const p = msg.payload;
const colours = { AVAILABLE: "#2e7d32", OCCUPIED: "#e53935", SENSOR_ERROR: "#ef6c00", UNKNOWN: "#717171" };
const labels = { AVAILABLE: "AVAILABLE", OCCUPIED: "OCCUPIED", SENSOR_ERROR: "SENSOR FAULT", UNKNOWN: "UNKNOWN" };

const text = labels[p.status] + (p.distance_cm >= 0 ? " (" + p.distance_cm.toFixed(1) + " cm)" : "");
const out = new Array(node.outputCount).fill(null);
out[p.slot - 1] = { payload: text, ui_update: { color: colours[p.status] } };
return out;

const SLOT_COUNT = Number(env.get("SLOT_COUNT") || 3);
const states = flow.get("parkingStates") || {};
states[msg.payload.slot] = msg.payload.status;
flow.set("parkingStates", states);

let available = 0, occupied = 0, faults = 0;
for (let s = 1; s <= SLOT_COUNT; s++) {
    const st = states[s] || "UNKNOWN";
    if (st === "AVAILABLE") available++;
    else if (st === "OCCUPIED") occupied++;
    else if (st === "SENSOR_ERROR") faults++;
}
const unknown = SLOT_COUNT - available - occupied - faults;
const rate = Math.round((occupied / SLOT_COUNT) * 1000) / 10;

let alert = "No alerts";
let alertColour = "#2e7d32";
if (occupied === SLOT_COUNT) {
    alert = "All parking slots occupied";
    alertColour = "#e53935";
} else if (faults > 0) {
    alert = faults + " sensor fault(s) - check the sensors";
    alertColour = "#ef6c00";
}

return [
    { payload: "Total " + SLOT_COUNT + " | Free " + available + " | Occupied " + occupied +
               " | Fault " + faults + " | Unknown " + unknown },
    { payload: available },
    { payload: occupied },
    { payload: rate + " %" },
    { payload: alert, ui_update: { color: alertColour } }
];

// Store only real state changes. The ESP32 repeats its status every 10 s;
// repeating the same status is not a new event, so it is not stored again.
const p = msg.payload;
if (p.status === "UNKNOWN") return null;

const last = flow.get("lastLogged") || {};
if (last[p.slot] === p.status) return null;
last[p.slot] = p.status;
flow.set("lastLogged", last);

// Parameterised query: values are bound, never pasted into the SQL text.
msg.topic = "INSERT INTO parking_logs (slot, status, distance_cm, uptime_ms, boot_id, seq) " +
            "VALUES ($slot, $status, $distance, $uptime, $boot, $seq)";
msg.payload = [p.slot, p.status, p.distance_cm, p.uptime_ms, p.boot, p.seq];
return msg;

const p = msg.payload;
const online = p.state === "ONLINE";
const display = {
    payload: (online ? "ONLINE" : "OFFLINE") + " (boot " + p.boot + ")",
    ui_update: { color: online ? "#2e7d32" : "#e53935" }
};
// A retained copy delivered when Node-RED subscribes is not a new event.
if (msg.retain) return [display, null];
return [display, {
    topic: "INSERT INTO system_events (event, detail) VALUES ($event, $detail)",
    payload: ["DEVICE_" + p.state, "boot " + p.boot + ", seq " + p.seq]
}];

const p = msg.payload;
const count = (flow.get("rejectedCount") || 0) + 1;
flow.set("rejectedCount", count);
const time = new Date().toLocaleTimeString();
return [
    { payload: count, ui_update: { color: "#e53935" } },
    { payload: time + " - " + p.reason + " (" + p.topic + ")" },
    { topic: "INSERT INTO security_events (reason, topic, payload) VALUES ($reason, $topic, $payload)",
      payload: [p.reason, p.topic, p.raw] }
];

// Checks every message on the subscribed smart parking topics before anything else uses it.
// Output 1 = slot status, 2 = slot event, 3 = connection, 4 = rejected.
const SECRET = env.get("SMARTPARKING_HMAC_SECRET");
const SLOT_COUNT = Number(env.get("SLOT_COUNT") || 3);
const STATES = ["UNKNOWN", "AVAILABLE", "OCCUPIED", "SENSOR_ERROR"];

function reject(reason) {
    const raw = typeof msg.payload === "string" ? msg.payload : JSON.stringify(msg.payload);
    node.warn("Rejected " + msg.topic + ": " + reason);
    return [null, null, null, {
        topic: msg.topic,
        payload: { reason: reason, topic: msg.topic, raw: String(raw).slice(0, 300) }
    }];
}

if (!SECRET) {
    node.error("SMARTPARKING_HMAC_SECRET is not set - start Node-RED with npm start");
    return null;
}
if (msg.topic === "smartparking/command") {
    return null; // commands go to the device, not to Node-RED
}

let d;
try {
    d = JSON.parse(msg.payload);
} catch (e) {
    return reject("payload is not valid JSON");
}
if (typeof d !== "object" || d === null || Array.isArray(d)) {
    return reject("payload is not a JSON object");
}

const isHex = (v, n) => typeof v === "string" && new RegExp("^[0-9a-f]{" + n + "}$").test(v);
if (!isHex(d.boot, 8)) return reject("missing or invalid boot ID");
if (!Number.isInteger(d.seq) || d.seq < 1) return reject("missing or invalid sequence number");
if (!isHex(d.sig, 64)) return reject("missing signature");

let kind, canonical, replayKey;
const m = msg.topic.match(/^smartparking\/slot(\d+)\/(status|event)$/);
if (m) {
    kind = m[2];
    const slot = Number(m[1]);
    if (d.slot !== slot || slot < 1 || slot > SLOT_COUNT) {
        return reject("slot number does not match topic or is out of range");
    }
    if (typeof d.distance_cm !== "number" || !Number.isFinite(d.distance_cm) ||
        d.distance_cm < -1 || d.distance_cm > 500) {
        return reject("distance_cm out of range");
    }
    if (!Number.isInteger(d.uptime_ms) || d.uptime_ms < 0) return reject("invalid uptime_ms");
    const dist = d.distance_cm.toFixed(1);
    if (kind === "status") {
        if (!STATES.includes(d.status)) return reject("unknown status value");
        canonical = ["status", slot, d.status, dist, d.uptime_ms, d.boot, d.seq].join("|");
    } else {
        if (!STATES.includes(d.from) || !STATES.includes(d.to)) return reject("unknown state in event");
        canonical = ["event", slot, d.from, d.to, dist, d.uptime_ms, d.boot, d.seq].join("|");
    }
    replayKey = d.boot + "|" + kind + "|" + slot;
} else if (msg.topic === "smartparking/system/connection") {
    kind = "conn";
    if (!["ONLINE", "OFFLINE"].includes(d.state)) return reject("unknown connection state");
    canonical = ["conn", d.state, d.boot, d.seq].join("|");
    replayKey = d.boot + "|conn|" + d.state;
} else {
    return reject("unexpected topic");
}

// Authenticity and integrity: HMAC-SHA256 with the shared secret.
const expected = crypto.createHmac("sha256", SECRET).update(canonical).digest();
if (!crypto.timingSafeEqual(expected, Buffer.from(d.sig, "hex"))) {
    return reject("signature check failed (forged or modified message)");
}

// Replay protection: sequence numbers must increase per boot, topic and slot.
let seen = flow.get("lastSeq") || {};
if (Object.keys(seen).length > 1000) seen = {};
const last = seen[replayKey];
if (last !== undefined && d.seq <= last) {
    if (msg.retain) return null; // broker re-sent a retained copy we already handled
    return reject("replayed message (sequence " + d.seq + " already used)");
}
seen[replayKey] = d.seq;
flow.set("lastSeq", seen);

delete d.sig;
msg.kind = kind;
msg.payload = d;
const outputs = [null, null, null, null];
outputs[{ status: 0, event: 1, conn: 2 }[kind]] = msg;
return outputs;

// Start the change detector from what is already in the database,
// so a restart of Node-RED does not store a duplicate row.
const last = {};
for (const row of msg.payload) last[row.slot] = row.status;
flow.set("lastLogged", last);
node.status({ text: "loaded " + msg.payload.length + " slot(s)" });
return null;

msg.topic = "SELECT p.slot, p.status FROM parking_logs p " +
            "WHERE p.id = (SELECT MAX(p2.id) FROM parking_logs p2 WHERE p2.slot = p.slot)";
msg.payload = [];
return msg;

msg.topic = "SELECT id, slot, status, distance_cm, datetime(timestamp, 'localtime') AS local_time " +
            "FROM parking_logs ORDER BY id DESC LIMIT 20";
msg.payload = [];
return msg;

// Run once at start-up. busy_timeout makes SQLite wait up to 5 s instead of failing
// at once when another program (DB Browser, the tests) is using the file.
// WAL mode lets reads and writes happen at the same time.
return [[
    { topic: "PRAGMA busy_timeout = 5000", payload: [] },
    { topic: "PRAGMA journal_mode = WAL", payload: [] }
]];
